<?php
declare(strict_types=1); require_once __DIR__.'/includes/functions.php';
if(!installed()){redirect('/install.php');}
$q=trim($_GET['q']??''); $sql='SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.is_active=1'; $params=[]; if($q!==''){ $sql.=' AND (p.name LIKE ? OR p.description LIKE ?)'; $params=["%$q%","%$q%"];} $sql.=' ORDER BY p.created_at DESC'; $st=db()->prepare($sql);$st->execute($params);$products=$st->fetchAll();
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e(setting('shop_name'))?></title><meta name="description" content="<?=e(setting('tagline'))?>"><link rel="stylesheet" href="/public/css/app.css"></head><body><header class="top"><a class="brand" href="/"><?=e(setting('shop_name'))?></a><a href="/login.php">Admin</a></header><main class="container"><section class="hero"><span class="badge">Catalogue</span><h1><?=e(setting('shop_name'))?></h1><p><?=e(setting('tagline'))?></p><form class="search"><input name="q" value="<?=e($q)?>" placeholder="Rechercher un produit..."><button>Rechercher</button></form></section><section class="grid"><?php foreach($products as $p): ?><article class="card"><a href="/product.php?slug=<?=urlencode($p['slug'])?>"><?php if($p['image']):?><img src="/<?=e(UPLOAD_URL.$p['image'])?>" alt="<?=e($p['name'])?>"><?php else:?><div class="placeholder">🛍️</div><?php endif;?></a><div class="card-body"><small><?=e($p['category_name']??'')?></small><h2><?=e($p['name'])?></h2><strong><?=money($p['price'])?></strong><a class="btn whatsapp" href="<?=e(whatsapp_link(setting('whatsapp_number'),$p['name'],(float)$p['price']))?>" target="_blank" rel="noopener">Commander sur WhatsApp</a></div></article><?php endforeach;?></section><?php if(!$products):?><p class="empty">Aucun produit trouvé.</p><?php endif;?></main></body></html>